const skies={orion:{name:'Orion',subtitle:'The Hunter',copy:'Three bright stars form a belt at the heart of this familiar pattern. Across cultures and centuries, Orion has inspired stories of a figure set against the night.',index:'01 / 03',points:[[125,78],[270,72],[245,165],[220,195],[190,204],[160,213],[125,300],[275,318],[245,165],[300,130]],paths:[[0,2,3,4,5,6],[1,2,7],[2,9]]},cygnus:{name:'Cygnus',subtitle:'The Swan',copy:'A long cross of stars suggests a swan in flight. Its graceful outline invites the eye to travel along the imagined wings and neck of a celestial bird.',index:'02 / 03',points:[[200,62],[196,145],[193,210],[190,310],[95,160],[145,187],[250,182],[309,151]],paths:[[0,1,2,3],[4,5,2,6,7]]},cassiopeia:{name:'Cassiopeia',subtitle:'The Queen',copy:'Five prominent stars form a distinctive zigzag, often imagined as a W. It is a simple shape with a long history of stories attached to its points of light.',index:'03 / 03',points:[[72,165],[134,250],[202,148],[269,234],[330,133]],paths:[[0,1,2,3,4]]}};const svgNS='http://www.w3.org/2000/svg';const map=document.querySelector('#map');function draw(key){const c=skies[key];map.replaceChildren();const bg=[[44,100],[95,67],[334,75],[350,245],[85,300],[294,290],[56,230],[250,55],[178,337],[315,195],[120,135],[275,350],[210,110],[70,185],[340,320],[145,355],[230,260]];bg.forEach(([x,y],i)=>{let dot=document.createElementNS(svgNS,'circle');dot.setAttribute('cx',x);dot.setAttribute('cy',y);dot.setAttribute('r',i%4===0?'1.5':'.8');dot.setAttribute('fill','#cfbf9c');dot.setAttribute('opacity','.45');map.append(dot)});c.paths.forEach(path=>{let line=document.createElementNS(svgNS,'polyline');line.setAttribute('points',path.map(i=>c.points[i].join(',')).join(' '));line.setAttribute('fill','none');line.setAttribute('stroke','#c7a975');line.setAttribute('stroke-width','1');line.setAttribute('opacity','.8');map.append(line)});c.points.forEach(([x,y],i)=>{let glow=document.createElementNS(svgNS,'circle');glow.setAttribute('cx',x);glow.setAttribute('cy',y);glow.setAttribute('r',i%3===0?'8':'5');glow.setAttribute('fill','#ebd9aa');glow.setAttribute('opacity','.14');map.append(glow);let dot=document.createElementNS(svgNS,'circle');dot.setAttribute('cx',x);dot.setAttribute('cy',y);dot.setAttribute('r',i%3===0?'3.3':'2.3');dot.setAttribute('fill','#f7e9ca');map.append(dot)});map.setAttribute('aria-label','Illustrative diagram of '+c.name);document.querySelector('#constellation-name').textContent=c.name;document.querySelector('#constellation-subtitle').textContent=c.subtitle;document.querySelector('#constellation-copy').textContent=c.copy;document.querySelector('#map-index').textContent=c.index;document.querySelectorAll('.constellation').forEach(button=>{const active=button.dataset.constellation===key;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active))})}document.querySelectorAll('.constellation').forEach(button=>button.addEventListener('click',()=>draw(button.dataset.constellation)));draw('orion');
